fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    let n = nums.len();
    if n == 0 {
        return 0;
    }

    let mut best = 1usize;
    let mut curr = 1usize;

    for i in 1..n {
        if nums[i] > nums[i - 1] {
            curr += 1;
        } else {
            curr = 1;
        }
        if curr > best {
            best = curr;
        }
    }

    best
}